__define('js/core/game-state.js', function () {
/** The one game state. Modules read it, patch it, and subscribe to changes. */
const INITIAL_STATE = Object.freeze({
  screen: 'boot',
  currentLevelIndex: 0,
  bridgeProgress: 0,          // number of stages built
  craneState: 'locked',
  craneBusy: false,          // a scripted crane motion or sequence is running
  craneX: 0,
  hoistY: 0,
  carriedTriangleId: null,
  hoveredOptionId: null,
  activeSocketId: null,
  isInputLocked: true,
  transition: null,           // name of the running screen/level transition, if any
  audioMuted: false,
  completed: false,
});

function createGameState() {
  let state = { ...INITIAL_STATE };
  const listeners = new Set();

  return {
    get() {
      return state;
    },
    update(patch) {
      let changed = false;
      for (const key of Object.keys(patch)) {
        if (state[key] !== patch[key]) {
          changed = true;
          break;
        }
      }
      if (!changed) return state;
      state = { ...state, ...patch };
      for (const listener of listeners) listener(state, patch);
      return state;
    },
    reset(overrides = {}) {
      state = { ...INITIAL_STATE, audioMuted: state.audioMuted, ...overrides };
      for (const listener of listeners) listener(state, state);
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}
  return { createGameState };
});
__define('js/core/game-loop.js', function () {
/** Single requestAnimationFrame loop shared by every per-frame system. */
function createGameLoop() {
  const subscribers = new Set();
  let running = false;
  let lastTime = 0;

  function frame(now) {
    if (!running) return;
    const deltaSeconds = Math.min(0.05, (now - lastTime) / 1000 || 0);
    lastTime = now;
    for (const update of subscribers) update(deltaSeconds, now);
    requestAnimationFrame(frame);
  }

  return {
    start() {
      if (running) return;
      running = true;
      lastTime = performance.now();
      requestAnimationFrame(frame);
    },
    stop() {
      running = false;
    },
    add(update) {
      subscribers.add(update);
      return () => subscribers.delete(update);
    },
  };
}
  return { createGameLoop };
});
__define('js/core/asset-loader.js', function () {
/** Preloads raster assets before the game starts. Optional assets may be missing (documented hooks). */
function preloadImages(entries, onProgress) {
  const loaded = new Set();
  const missing = new Set();
  let finished = 0;

  const tasks = entries.map(({ key, src, optional = false }) =>
    new Promise((resolve) => {
      const image = new Image();
      const done = (ok) => {
        finished += 1;
        (ok ? loaded : missing).add(key);
        onProgress?.(finished / entries.length, key, ok);
        resolve();
      };
      image.onload = () => done(true);
      image.onerror = () => {
        if (!optional) console.error(`[assets] missing required asset: ${src}`);
        done(false);
      };
      image.decoding = 'async';
      image.src = src;
    })
  );

  return Promise.all(tasks).then(() => ({ loaded, missing }));
}
  return { preloadImages };
});
