  const button = document.createElement('button');
  button.type = 'button';
  button.className = `cta-button icon-cta icon-cta--${icon} overlay-cta`;
  button.setAttribute('aria-label', label);
  button.innerHTML = ICONS[icon] ?? '';
  let pressed = false;
